// Package graph hosts the GraphQL endpoint that fronts the ent client.
//
// The schema is generated by entgql (see internal/ent/entc.go); the
// resolver glue is generated by gqlgen (see gqlgen.yml). This package
// adds the resolver constructor and root server factory; everything
// else is generated.
package graph

import (
	"context"

	"github.com/99designs/gqlgen/graphql"
	"github.com/rs/zerolog"

	"github.com/nicolerenee/promptbook/internal/ent"
	"github.com/nicolerenee/promptbook/internal/imagecache"
	"github.com/nicolerenee/promptbook/internal/ingest"
	"github.com/nicolerenee/promptbook/internal/nforefresh"
	"github.com/nicolerenee/promptbook/internal/probe"
)

// IngestRunner is the slice of *ingest.Engine the importQueueEntry
// mutation needs. Surfaced here (not in the parent server package) so
// the graph resolver can hold one without importing server (which
// imports graph). Callers building a Resolver pass the same
// *ingest.Engine they pass on Server.Options.IngestEngine; the
// server-side IngestRunner alias points at this declaration so the
// satisfaction check stays in one place.
type IngestRunner interface {
	Ingest(ctx context.Context, src string, opts ingest.Options) (*ingest.Result, error)
}

// LibraryPlan carries the rename Plan inputs the previewQueueImport
// resolver needs (LibraryRoot + the two templates + a Prober for the
// new media-info tokens). The IngestRunner interface deliberately
// doesn't expose these — Plan-side previews are a separate read
// surface from the engine's Apply path. Pass the zero value when no
// library is configured; the resolver returns a "library not
// configured" error in that mode.
//
// Prober may be nil when the resolver is exercised in tests that don't
// care about probe-derived tokens; the helper degrades to an empty
// MediaInfo in that case so the optional-segment grammar collapses
// the absent fields rather than failing.
type LibraryPlan struct {
	Root           string
	FolderTemplate string
	FileTemplate   string
	Prober         probe.Prober
}

// Configured reports whether the LibraryPlan carries enough to drive
// rename.BuildPlan. Root + both templates must be non-empty; Prober
// is optional (the resolver passes an empty MediaInfo when nil so
// previews still render before ffprobe is wired up).
func (p LibraryPlan) Configured() bool {
	return p.Root != "" && p.FolderTemplate != "" && p.FileTemplate != ""
}

// Resolver is the root resolver. It carries the ent client every
// generated resolver method calls into, plus the image cache the
// enrichment resolvers (poster URL, fanart URL, headshot URL) use to
// derive `/images/...` paths from int64 entity ids, plus the ingest
// engine the importQueueEntry mutation drives + a logger for the
// fire-and-forget cleanup paths.
//
// imageCache may be nil — when caching is disabled, the URL helpers
// return empty strings so the SPA renders its placeholder branch.
// ingestEngine may be nil — when nil the importQueueEntry resolver
// returns a "ingest not configured" error so the rest of the read
// surface stays alive. libraryPlan may be the zero value — when not
// Configured() the previewQueueImport resolver returns a "library
// not configured" error. nfoRefresh may be nil — when nil the
// regenerateRecordingNFO mutation + the apply-rename's post-move
// rewrite return a typed error so the rest of the schema stays
// usable; in production it's wired whenever the image cache is.
type Resolver struct {
	client       *ent.Client
	imageCache   *imagecache.Cache
	ingestEngine IngestRunner
	libraryPlan  LibraryPlan
	nfoRefresh   *nforefresh.Service
	logger       zerolog.Logger
}

// NewSchema builds an executable GraphQL schema rooted at the supplied
// ent client + image cache + ingest runner + library plan + nfo
// refresh service + logger. The image cache, ingest runner, and nfo
// refresh service are all optional; pass nil when the surface is not
// configured at the server layer. libraryPlan may be the zero value
// when no library.root / templates are configured.
func NewSchema(
	client *ent.Client,
	cache *imagecache.Cache,
	ingestEngine IngestRunner,
	libraryPlan LibraryPlan,
	nfoRefresh *nforefresh.Service,
	logger zerolog.Logger,
) graphql.ExecutableSchema {
	return NewExecutableSchema(Config{
		Resolvers: &Resolver{
			client:       client,
			imageCache:   cache,
			ingestEngine: ingestEngine,
			libraryPlan:  libraryPlan,
			nfoRefresh:   nfoRefresh,
			logger:       logger,
		},
	})
}
